how_to_use:
bool _isSelected = false;

ChoiceChip(
  label: Text('Option 1'),
  selected: _isSelected,
  onSelected: (bool selected) {
    setState(() {
      _isSelected = selected;
    });
  },
  selectedColor: Colors.blue,
  backgroundColor: Colors.grey[200],
  labelStyle: TextStyle(color: Colors.white),
);
